using System.Text.Json;
using OpenNV.Runtime.Content;
using OpenNV.Runtime.Gameplay.State;

internal static partial class SourceMainScriptCallerContracts
{
    // The outer prefix DTO is authored. Child receipts are generated by the
    // real C# owners under authored scopes. This never executes the whole Main.
    internal static void RunLateFramePrefixValidationContracts()
    {
        using var actor = new LateActorTimeFixture();
        var actorCall = actor.Enter(); var invocation = actorCall.Invocation;
        var source = FalloutPlayerLateFramePrefixSource.Reviewed(actor.Capture().Source.Following);
        var moverSource = FalloutActorMoverSource.Reviewed(source.Following.Controls);
        var thread = Environment.CurrentManagedThreadId;
        var moverInvocation = new FalloutActorMoverFrameInvocation(invocation.Caller, invocation.PlayerProcess, invocation.Common, thread);
        var mover = CreateMover(); var otherMover = CreateMover();
        var inhibition = new FalloutPlayerInhibitionState(source.Following, actor.Base.Stack,
            invocation.PlayerProcess, invocation.PlayerConstructor, (consumer, caller) =>
            {
                if (consumer != FalloutPlayerInhibitionConsumer.LateFrame || caller != invocation.Caller || thread != Environment.CurrentManagedThreadId)
                    throw new InvalidOperationException("Authored late prefix inhibition lost its entered caller.");
            });
        try
        {
            var flags = mover.StorePlayerFrameFlags(moverInvocation, 0);
            var vector = mover.StorePlayerFrameDefaultVector(moverInvocation);
            var reads = new[] { inhibition.ReadLateFrameLane(invocation.Caller, FalloutPlayerInhibitionLane.Second),
                inhibition.ReadLateFrameLane(invocation.Caller, FalloutPlayerInhibitionLane.First) };
            var call = new FalloutPlayerLateFrameCall(source.Identity, actor.Base.Stack, invocation, 1, 40,
                FalloutPlayerLateFrameStep.Failed, FalloutPlayerLateFrameStep.MoverDelta,
                ViewRequest: 0, MoverWord: 0, Flags: flags, SharedTimerBits: 0, InhibitionReads: reads,
                DesiredView: 0, ComparedView: 0, ActorTime: actorCall, DefaultVector: vector,
                Failure: FalloutStandalonePlayerSceneState.LateMoverDeltaBoundary);
            var actual = RoundTripPackage(mover.Capture());
            Validate(call, actual);
            Reject(() => Validate(call with { FailedAt = (FalloutPlayerLateFrameStep)999 }, actual));
            Reject(() => Validate(call with { FailedAt = FalloutPlayerLateFrameStep.Failed }, actual));
            Reject(() => Validate(call with { ViewRequest = null }, actual));
            Reject(() => Validate(call with { MoverWord = null }, actual));
            Reject(() => Validate(call with { Flags = null }, actual));
            Reject(() => Validate(call with { SharedTimerBits = null }, actual));
            Reject(() => Validate(call with { InhibitionReads = null }, actual));
            Reject(() => Validate(call with { InhibitionReads = [] }, actual));
            Reject(() => Validate(call with { InhibitionReads = [reads[0]] }, actual));
            Reject(() => Validate(call with { DesiredView = null }, actual));
            Reject(() => Validate(call with { ComparedView = null }, actual));
            Reject(() => Validate(call with { ActorTime = null }, actual));
            Reject(() => Validate(call with { DefaultVector = null }, actual));
            Reject(() => Validate(call with { Invocation = invocation with { ThreadId = 0 } }, actual));
            Reject(() => Validate(call with { Invocation = invocation with { Prelude = Guid.Empty } }, actual));
            Reject(() => Validate(call with { FailedAt = FalloutPlayerLateFrameStep.SharedTimer }, actual));
            Reject(() => Validate(call with { FailedAt = FalloutPlayerLateFrameStep.SecondInhibition }, actual));
            Reject(() => Validate(call with { FailedAt = FalloutPlayerLateFrameStep.ViewComparison }, actual));

            // Both alternatives are independently valid receipts with the same
            // caller/process/Common. Their factories identify another owner.
            var foreignFlags = otherMover.StorePlayerFrameFlags(moverInvocation, 0);
            var foreignVector = otherMover.StorePlayerFrameDefaultVector(moverInvocation);
            var foreignOwner = RoundTripPackage(otherMover.Capture());
            FalloutActorMoverState.Validate(foreignOwner, moverSource, actor.Base.Stack);
            Require(flags.Factory != foreignFlags.Factory && vector.Factory != foreignVector.Factory,
                "Authored mover-owner exchange did not create distinct real factories.");
            Reject(() => Validate(call with { Flags = foreignFlags }, actual));
            Reject(() => Validate(call with { DefaultVector = foreignVector }, actual));
            Reject(() => Validate(call, foreignOwner));

            var clonedCall = JsonSerializer.Deserialize<FalloutPlayerLateFrameCall>(JsonSerializer.Serialize(call))!;
            var clonedOwner = RoundTripPackage(actual);
            Require(!ReferenceEquals(clonedCall.Flags!.Stores, clonedOwner.PlayerFrame!.Flags!.Stores) &&
                !ReferenceEquals(clonedCall.DefaultVector!.Stores, clonedOwner.PlayerFrame.Vector!.Stores),
                "The cold structural-join test accidentally shared list instances.");
            Validate(clonedCall, clonedOwner);

            // A reached setter may genuinely fail before XY, or after XY and
            // before Z. Those actual owner prefixes remain valid observations.
            ValidateFailedVector(afterXY: false);
            ValidateFailedVector(afterXY: true);
            Console.WriteLine("OPENNV_LATE_FRAME_PREFIX_VALIDATION_PASS enumAndPassedChildren=true actualMoverJoins=true " +
                "independentJsonChildren=true retainedPartialVector=true outerPrefix=AUTHORED wholeMain=UNEXECUTED campaign=UNEXECUTED");

            void ValidateFailedVector(bool afterXY)
            {
                var guards = 0; var inVector = false;
                var partial = new FalloutActorMoverState(moverSource, actor.Base.Stack,
                    invocation.PlayerProcess, invocation.PlayerConstructor, Lifetime);
                partial.BindPlayerFrame(invocation.Common.Actor, current =>
                {
                    Guard(current);
                    if (!inVector || ++guards != (afterXY ? 3 : 2)) return;
                    try { _ = partial.Capture(); } catch (InvalidOperationException) { }
                });
                try
                {
                    var returnedFlags = partial.StorePlayerFrameFlags(moverInvocation, 0); inVector = true;
                    Reject(() => partial.StorePlayerFrameDefaultVector(moverInvocation));
                    var failedOwner = RoundTripPackage(partial.Capture()); var failedVector = failedOwner.PlayerFrame!.Vector!;
                    Require(!failedVector.Returned && failedVector.Stores.Count == (afterXY ? 1 : 0),
                        "The partial-vector fixture fabricated a return or lost the actual committed XY prefix.");
                    var failedCall = call with { Flags = returnedFlags, DefaultVector = failedVector,
                        FailedAt = FalloutPlayerLateFrameStep.DefaultVector, Failure = failedVector.Failure };
                    Validate(RoundTripPackage(failedCall), failedOwner);
                    Reject(() => Validate(failedCall with { FailedAt = FalloutPlayerLateFrameStep.MoverDelta }, failedOwner));
                }
                finally { partial.Retire(); }
            }
        }
        finally { mover.Retire(); otherMover.Retire(); inhibition.Retire(); }

        FalloutActorMoverState CreateMover()
        {
            var value = new FalloutActorMoverState(moverSource, actor.Base.Stack, invocation.PlayerProcess, invocation.PlayerConstructor, Lifetime);
            value.BindPlayerFrame(invocation.Common.Actor, Guard); return value;
        }
        void Guard(FalloutActorMoverFrameInvocation current)
        {
            Lifetime();
            if (current != moverInvocation || current.Common != actor.Base.Common.ReadSceneQueries(actor.Base.Actor.Reference, 1))
                throw new InvalidOperationException("Authored late prefix mover lost its entered Common/caller scope.");
        }
        void Lifetime()
        {
            if (thread != Environment.CurrentManagedThreadId)
                throw new InvalidOperationException("Authored late prefix changed its owner thread.");
        }
        void Validate(FalloutPlayerLateFrameCall value, FalloutActorMoverSnapshot actualMover)
        {
            FalloutStandalonePlayerSceneState.ValidateLateFrameCall(value, source, actor.Base.Stack);
            FalloutStandalonePlayerSceneState.ValidateLateFrameMoverJoins(value, actualMover);
        }
    }
}
